/* Explicit hidden attribute rule to prevent any specificity override */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1a1c23;
  --color-card: #272a34;
  --color-primary: #38bdf8;
  --color-accent: #facc15;
  --color-rest: #34d399;
  --color-work: #f87171;
  --color-text: #f8fafc;
  --color-muted: #94a3b8;
  --color-dark: #0f172a;
  --border-size: 4px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 16px;
}

.container {
  width: 100%;
  max-width: 440px;
  margin: 0 auto;
}

/* Pixel Card Container */
.pixel-card {
  background-color: var(--color-card);
  border: var(--border-size) solid var(--color-dark);
  box-shadow:
    inset -4px -4px 0px 0px rgba(0, 0, 0, 0.4),
    inset 4px 4px 0px 0px rgba(255, 255, 255, 0.1),
    8px 8px 0px 0px var(--color-dark);
  padding: 24px;
  text-align: center;
}

.card-header {
  margin-bottom: 20px;
}

.title {
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--color-primary);
  text-shadow: 2px 2px 0px var(--color-dark);
}

.pixel-divider {
  height: 4px;
  background-color: var(--color-dark);
  margin: 12px auto 0;
  box-shadow: 0 2px 0 0 rgba(255, 255, 255, 0.1);
}

/* Status Grid */
.status-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-bottom: 24px;
}

.status-item {
  background-color: var(--color-dark);
  padding: 10px;
  border: 2px solid #334155;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.label {
  font-size: 0.85rem;
  color: var(--color-muted);
  font-weight: bold;
  letter-spacing: 1px;
}

.value {
  font-size: 1.25rem;
  font-weight: bold;
  letter-spacing: 1px;
}

.phase-work {
  color: var(--color-work);
}

.phase-rest {
  color: var(--color-rest);
}

/* Countdown Display */
.countdown-box {
  background-color: var(--color-dark);
  border: var(--border-size) solid #334155;
  box-shadow: inset 4px 4px 0px 0px rgba(0, 0, 0, 0.6);
  padding: 24px 16px;
  margin-bottom: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.countdown-timer {
  font-size: 4rem;
  line-height: 1;
  font-weight: bold;
  color: var(--color-text);
  font-variant-numeric: tabular-nums;
  text-shadow: 3px 3px 0px rgba(0, 0, 0, 0.8);
}

.countdown-unit {
  margin-top: 8px;
  font-size: 0.9rem;
  letter-spacing: 2px;
  color: var(--color-muted);
}

/* Pixel Button Controls */
.controls-group {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.pixel-btn {
  appearance: none;
  border: var(--border-size) solid var(--color-dark);
  padding: 12px 16px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 1px;
  cursor: pointer;
  outline: none;
  position: relative;
  user-select: none;
  box-shadow: 4px 4px 0px 0px var(--color-dark);
  transition: transform 0.05s ease, box-shadow 0.05s ease;
}

.pixel-btn:hover {
  filter: brightness(1.1);
}

.pixel-btn:focus-visible {
  outline: 3px dashed var(--color-accent);
  outline-offset: 4px;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0px 0px var(--color-dark);
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-dark);
}

.btn-secondary {
  background-color: var(--color-accent);
  color: var(--color-dark);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-text);
  border-color: #475569;
  box-shadow: 4px 4px 0px 0px #0f172a;
}

/* Workout Complete Screen */
.complete-view {
  padding: 24px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
}

.complete-badge {
  font-size: 2rem;
  color: var(--color-accent);
  letter-spacing: 6px;
}

.complete-text {
  font-size: 1.75rem;
  color: var(--color-rest);
  text-transform: uppercase;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0px var(--color-dark);
}

.complete-subtext {
  color: var(--color-muted);
  font-size: 1rem;
  margin-bottom: 8px;
}

@media (min-width: 400px) {
  .controls-group {
    flex-direction: row;
  }

  .controls-group .pixel-btn {
    flex: 1;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const WORK_SECONDS = 40;
  const REST_SECONDS = 20;
  const TOTAL_SETS = 3;

  // Application State
  let currentSet = 1;
  let currentPhase = 'Work'; // 'Work' | 'Rest'
  let remainingSeconds = WORK_SECONDS;
  let timerInterval = null;
  let isRunning = false;

  // DOM Elements
  const activeView = document.getElementById('active-view');
  const completeView = document.getElementById('complete-view');
  const phaseDisplay = document.getElementById('phase-display');
  const setDisplay = document.getElementById('set-display');
  const timeDisplay = document.getElementById('time-display');
  const startPauseBtn = document.getElementById('start-pause-btn');
  const skipBtn = document.getElementById('skip-btn');
  const resetBtn = document.getElementById('reset-btn');
  const restartBtn = document.getElementById('restart-btn');

  function updateDisplay() {
    phaseDisplay.textContent = currentPhase;
    phaseDisplay.className = `value ${currentPhase === 'Work' ? 'phase-work' : 'phase-rest'}`;
    setDisplay.textContent = `${currentSet} / ${TOTAL_SETS}`;
    timeDisplay.textContent = remainingSeconds;
    startPauseBtn.textContent = isRunning ? 'Pause' : 'Start';
  }

  function stopTimer() {
    if (timerInterval) {
      clearInterval(timerInterval);
      timerInterval = null;
    }
    isRunning = false;
  }

  function completeWorkout() {
    stopTimer();
    activeView.hidden = true;
    completeView.hidden = false;
  }

  function advancePhase() {
    if (currentPhase === 'Work') {
      currentPhase = 'Rest';
      remainingSeconds = REST_SECONDS;
    } else {
      if (currentSet < TOTAL_SETS) {
        currentSet += 1;
        currentPhase = 'Work';
        remainingSeconds = WORK_SECONDS;
      } else {
        completeWorkout();
        return;
      }
    }
    updateDisplay();
  }

  function tick() {
    if (remainingSeconds > 1) {
      remainingSeconds -= 1;
      timeDisplay.textContent = remainingSeconds;
    } else {
      advancePhase();
    }
  }

  function startTimer() {
    if (!isRunning) {
      isRunning = true;
      startPauseBtn.textContent = 'Pause';
      timerInterval = setInterval(tick, 1000);
    }
  }

  function toggleStartPause() {
    if (isRunning) {
      stopTimer();
      startPauseBtn.textContent = 'Start';
    } else {
      startTimer();
    }
  }

  function handleSkip() {
    advancePhase();
  }

  function resetWorkout() {
    stopTimer();
    currentSet = 1;
    currentPhase = 'Work';
    remainingSeconds = WORK_SECONDS;
    activeView.hidden = false;
    completeView.hidden = true;
    updateDisplay();
  }

  // Attach Event Listeners
  startPauseBtn.addEventListener('click', toggleStartPause);
  skipBtn.addEventListener('click', handleSkip);
  resetBtn.addEventListener('click', resetWorkout);
  restartBtn.addEventListener('click', resetWorkout);

  // Initial render
  updateDisplay();
});
